export function up(db) {
  db.exec(`
    CREATE TABLE search_documents (
      issue_id TEXT PRIMARY KEY REFERENCES issues(id) ON DELETE CASCADE,
      org_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
      project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
      content_hash TEXT NOT NULL,
      comments_text TEXT NOT NULL DEFAULT '',
      indexed_at TEXT NOT NULL
    );
    CREATE INDEX search_documents_project ON search_documents(project_id, issue_id);
    CREATE TABLE search_terms (
      issue_id TEXT NOT NULL REFERENCES search_documents(issue_id) ON DELETE CASCADE,
      field TEXT NOT NULL,
      token TEXT NOT NULL,
      frequency INTEGER NOT NULL CHECK(frequency > 0),
      PRIMARY KEY(issue_id, field, token)
    );
    CREATE INDEX search_terms_prefix ON search_terms(token, issue_id, field);
    CREATE TABLE saved_filters (
      id TEXT PRIMARY KEY,
      org_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
      owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
      team_id TEXT REFERENCES teams(id) ON DELETE CASCADE,
      visibility TEXT NOT NULL CHECK(visibility IN ('personal','team')),
      name TEXT NOT NULL,
      description TEXT NOT NULL DEFAULT '',
      query TEXT NOT NULL,
      revision INTEGER NOT NULL DEFAULT 1,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL,
      CHECK((visibility='personal' AND team_id IS NULL) OR (visibility='team' AND team_id IS NOT NULL))
    );
    CREATE INDEX saved_filters_owner ON saved_filters(owner_id, org_id, updated_at, id);
    CREATE INDEX saved_filters_team ON saved_filters(team_id, updated_at, id);
  `);
}

import {createHash} from 'node:crypto';
import {searchTokens} from '@crew/shared';
import {getIssue} from '../work/issues.js';

export const SEARCH_WEIGHTS = Object.freeze({key: 14, title: 8, labels: 5, description: 2, comments: 1});

export function documentFields(issue, comments = '') {
  return {key: issue.key, title: issue.title, description: issue.description, labels: issue.labels.map(label => label.name).join(' '), comments};
}

export function indexIssue(ctx, issueId) {
  if (!ctx.db.prepare('SELECT 1 FROM issues WHERE id=?').get(issueId)) {
    ctx.db.prepare('DELETE FROM search_documents WHERE issue_id=?').run(issueId);
    return false;
  }
  const issue = getIssue(ctx, issueId);
  const comments = ctx.db.prepare('SELECT body FROM comments WHERE issue_id=? ORDER BY created_at,id').all(issueId).map(row => row.body).join('\n');
  const fields = documentFields(issue, comments);
  const hash = createHash('sha256').update(JSON.stringify(fields)).digest('hex');
  const current = ctx.db.prepare('SELECT content_hash FROM search_documents WHERE issue_id=?').get(issueId);
  if (current?.content_hash === hash) return false;
  ctx.transaction(() => {
    ctx.db.prepare(`INSERT INTO search_documents(issue_id,org_id,project_id,content_hash,comments_text,indexed_at)
      VALUES(?,?,?,?,?,?) ON CONFLICT(issue_id) DO UPDATE SET org_id=excluded.org_id,
      project_id=excluded.project_id,content_hash=excluded.content_hash,comments_text=excluded.comments_text,indexed_at=excluded.indexed_at`)
      .run(issue.id, issue.orgId, issue.projectId, hash, comments, ctx.now());
    ctx.db.prepare('DELETE FROM search_terms WHERE issue_id=?').run(issue.id);
    const insert = ctx.db.prepare('INSERT INTO search_terms(issue_id,field,token,frequency) VALUES(?,?,?,?)');
    for (const [field, text] of Object.entries(fields)) {
      const frequencies = new Map();
      for (const token of searchTokens(text)) frequencies.set(token, (frequencies.get(token) ?? 0) + 1);
      for (const [token, frequency] of frequencies) insert.run(issue.id, field, token, frequency);
    }
  });
  return true;
}

export function indexProject(ctx, projectId) {
  for (const row of ctx.db.prepare('SELECT id FROM issues WHERE project_id=? ORDER BY id').all(projectId)) indexIssue(ctx, row.id);
}

export function registerSearchIndex(ctx) {
  if (ctx.searchIndexRegistered) return;
  ctx.searchIndexRegistered = true;
  for (const row of ctx.db.prepare('SELECT id FROM issues ORDER BY id').all()) indexIssue(ctx, row.id);
  const unsubscribe = ctx.bus.subscribe(event => {
    if (event.entityType === 'issue') indexIssue(ctx, event.entityId);
    else if (event.entityType === 'comment') {
      const issueId = event.after?.issueId ?? event.before?.issueId ?? event.after?.issue?.id ?? event.before?.issue?.id;
      if (issueId) indexIssue(ctx, issueId);
    } else if (['label', 'project', 'workflow'].includes(event.entityType) && event.projectId) indexProject(ctx, event.projectId);
  });
  (ctx.cleanups ??= []).push(unsubscribe);
}

export function prefixScores(ctx, issueId, terms) {
  const rows = ctx.db.prepare('SELECT field,token,frequency FROM search_terms WHERE issue_id=?').all(issueId);
  let score = 0;
  for (const term of terms) {
    for (const token of searchTokens(term.value)) {
      for (const row of rows) {
        if (!row.token.startsWith(token)) continue;
        const exact = row.token === token ? 1.25 : 1;
        score += (SEARCH_WEIGHTS[row.field] ?? 1) * exact * (1 + Math.log2(row.frequency));
      }
    }
  }
  return score;
}

import {integer, suggestQuery} from '@crew/shared';
import {registerSearchIndex} from './search-index.js';
import {searchAccess, searchIssues} from './search.js';

export function suggestionCatalog(ctx, access) {
  const allowed = new Set(access.projectIds);
  const projects = ctx.db.prepare('SELECT id,key,name FROM projects WHERE org_id=? ORDER BY key,id').all(access.orgId).filter(row => allowed.has(row.id));
  const statuses = [];
  const labels = [];
  const assignees = new Map();
  for (const project of projects) {
    for (const status of ctx.db.prepare('SELECT name,category FROM project_statuses WHERE project_id=? ORDER BY position').all(project.id)) statuses.push({value: status.name, label: status.name, description: project.key + ' · ' + status.category});
    for (const label of ctx.db.prepare('SELECT id,name FROM labels WHERE project_id=? ORDER BY name').all(project.id)) labels.push({value: label.name, label: label.name, description: project.key});
    const members = ctx.db.prepare('SELECT u.id,u.name,u.email FROM memberships m JOIN users u ON u.id=m.user_id WHERE m.org_id=? ORDER BY u.name,u.id').all(access.orgId);
    for (const user of members) {
      if (ctx.permissions.canProject(user.id, project.id, 'project:read')) assignees.set(user.id, {value: user.id, label: user.name, description: user.email});
    }
  }
  return {projects: projects.map(project => ({value: project.key, label: project.key, description: project.name})), statuses, labels, assignees: [...assignees.values()]};
}

export function registerSearchRoutes(ctx) {
  registerSearchIndex(ctx);
  const {app, requireAuth} = ctx;
  app.get('/api/v1/search', requireAuth, (req, res) => res.json(searchIssues(ctx, req)));
  app.get('/api/v1/search/suggestions', requireAuth, (req, res) => {
    const access = searchAccess(ctx, req);
    const source = String(req.query.q ?? '').slice(0, 4000);
    const caret = integer(req.query.caret ?? source.length, 'caret', {min: 0, max: source.length});
    res.json({items: suggestQuery(source, suggestionCatalog(ctx, access), caret)});
  });
}

import {createHash} from 'node:crypto';
import {AppError, text, validatedQuery, evaluateQuery, positiveTerms, queryFilters, normalizeSearch, matchesText} from '@crew/shared';
import {encodeCursor} from '../../http/pagination.js';
import {getIssue} from '../work/issues.js';
import {documentFields, prefixScores} from './search-index.js';

export function searchAccess(ctx, req, query = req.query) {
  ctx.permissions.scope(req, 'insight:read');
  const orgId = text(query.orgId, 'orgId', {max: 100});
  if (!ctx.permissions.membership(req.user.id, orgId)) throw new AppError('FORBIDDEN', 'Organization permission denied', 403);
  let projects = ctx.permissions.projectIds(req.user.id, orgId).filter(id => ctx.permissions.canProject(req.user.id, id, 'insight:read'));
  if (query.projectId) {
    const project = ctx.permissions.assertProject(req, query.projectId, 'insight:read');
    if (project.org_id !== orgId) throw new AppError('VALIDATION', 'Project must belong to this organization', 422, {projectId: 'Choose a project in this organization'});
    projects = projects.filter(id => id === project.id);
  }
  return {orgId, projectIds: projects};
}

export function validateQueryProjects(ctx, ast, orgId, projectIds) {
  const accessible = new Set(projectIds);
  for (const filter of queryFilters(ast).filter(node => node.field === 'project')) {
    const project = ctx.db.prepare('SELECT id FROM projects WHERE org_id=? AND (id=? OR key=? COLLATE NOCASE)').get(orgId, filter.value, filter.value);
    if (!project || !accessible.has(project.id)) throw new AppError('FORBIDDEN', 'The query refers to an unavailable project', 403);
  }
}

export function highlightSegments(value, terms, {maximum = 320} = {}) {
  const source = String(value ?? '');
  const needles = terms.map(term => normalizeSearch(term.value)).filter(Boolean);
  const normalized = normalizeSearch(source);
  const first = Math.min(...needles.map(needle => normalized.indexOf(needle)).filter(index => index >= 0));
  const start = Number.isFinite(first) ? Math.max(0, first - 70) : 0;
  const end = Math.min(source.length, start + maximum);
  const selected = source.slice(start, end);
  const ranges = [];
  for (const needle of needles) {
    let offset = normalizeSearch(selected).indexOf(needle);
    while (offset >= 0) {
      ranges.push([offset, offset + needle.length]);
      offset = normalizeSearch(selected).indexOf(needle, offset + Math.max(needle.length, 1));
    }
  }
  ranges.sort((a, b) => a[0] - b[0] || b[1] - a[1]);
  const merged = [];
  for (const range of ranges) {
    const last = merged.at(-1);
    if (last && range[0] <= last[1]) last[1] = Math.max(last[1], range[1]);
    else merged.push([...range]);
  }
  const segments = start ? [{text: '…', match: false}] : [];
  let position = 0;
  for (const [from, to] of merged) {
    if (from > position) segments.push({text: selected.slice(position, from), match: false});
    segments.push({text: selected.slice(from, to), match: true});
    position = to;
  }
  if (position < selected.length) segments.push({text: selected.slice(position), match: false});
  if (end < source.length) segments.push({text: '…', match: false});
  return segments;
}

function facets(items, property) {
  const counts = new Map();
  for (const item of items) {
    const value = item[property] ?? 'unassigned';
    counts.set(value, (counts.get(value) ?? 0) + 1);
  }
  return [...counts].map(([value, count]) => ({value, count})).sort((a, b) => b.count - a.count || String(a.value).localeCompare(String(b.value)));
}

export function searchIssues(ctx, req, query = req.query) {
  const access = searchAccess(ctx, req, query);
  const {query: source, ast} = validatedQuery(query.q ?? query.query ?? '');
  validateQueryProjects(ctx, ast, access.orgId, access.projectIds);
  const terms = positiveTerms(ast);
  const allowed = new Set(access.projectIds);
  const documents = ctx.db.prepare('SELECT issue_id,project_id,comments_text FROM search_documents WHERE org_id=? ORDER BY issue_id').all(access.orgId).filter(row => allowed.has(row.project_id));
  const now = Date.parse(ctx.now());
  const results = [];
  for (const document of documents) {
    const issue = getIssue(ctx, document.issue_id);
    const searchable = {...issue, searchComments: document.comments_text};
    if (!evaluateQuery(ast, searchable, {userId: req.user.id})) continue;
    const fields = documentFields(issue, document.comments_text);
    const ageDays = Math.max(0, (now - Date.parse(issue.updatedAt)) / 86400000);
    const recency = 1 / (1 + ageDays / 30);
    let score = prefixScores(ctx, issue.id, terms) + recency;
    for (const term of terms.filter(item => item.quoted)) {
      if (matchesText(issue.title, term)) score += 20;
    }
    const matchFields = Object.entries(fields).filter(([, value]) => terms.some(term => matchesText(value, term))).map(([field]) => field);
    results.push({...issue, score: Number(score.toFixed(6)), matchFields, highlights: {
      title: highlightSegments(issue.title, terms, {maximum: 500}),
      description: highlightSegments(issue.description, terms),
      comments: highlightSegments(document.comments_text, terms)
    }});
  }
  results.sort((a, b) => b.score - a.score || b.updatedAt.localeCompare(a.updatedAt) || a.id.localeCompare(b.id));
  const {limit, cursor} = ctx.pagination(query);
  const fingerprint = createHash('sha256').update(JSON.stringify([req.user.id, access.orgId, query.projectId ?? null, source])).digest('hex');
  let start = 0;
  if (cursor) {
    if (cursor.fingerprint !== fingerprint || typeof cursor.id !== 'string') throw new AppError('VALIDATION', 'Cursor belongs to a different search', 422, {cursor: 'Run the query from its first page'});
    const index = results.findIndex(item => item.id === cursor.id);
    start = index < 0 ? results.length : index + 1;
  }
  const items = results.slice(start, start + limit);
  return {items, total: results.length, query: source,
    facets: {status: facets(results, 'statusName'), assignee: facets(results, 'assigneeId'), priority: facets(results, 'priority')},
    nextCursor: start + limit < results.length && items.length ? encodeCursor({fingerprint, id: items.at(-1).id}) : null};
}

