import {parseQuery} from './parser.js';

export const normalizeSearch = value => String(value ?? '').normalize('NFKC').toLocaleLowerCase('en-US');
export const searchTokens = value => normalizeSearch(value).match(/[\p{L}\p{N}_]+/gu) ?? [];

export function matchesText(value, term) {
  const text = normalizeSearch(value);
  const needle = normalizeSearch(term.value);
  if (term.quoted) return text.includes(needle);
  const words = searchTokens(needle);
  const haystack = searchTokens(text);
  return words.length > 0 && words.every(word => haystack.some(token => token.startsWith(word)));
}

function compare(actual, expected, operator) {
  if (operator === '!=') return actual !== expected;
  if (operator === '>') return actual > expected;
  if (operator === '>=') return actual >= expected;
  if (operator === '<') return actual < expected;
  if (operator === '<=') return actual <= expected;
  return actual === expected;
}

export function evaluateFilter(node, issue, context = {}) {
  const expected = normalizeSearch(node.value);
  let values;
  switch (node.field) {
    case 'status':
      values = [issue.statusId, issue.statusName, issue.statusCategory];
      break;
    case 'assignee':
      if (expected === '@me') values = [issue.assigneeId ? (issue.assigneeId === context.userId ? '@me' : issue.assigneeId) : 'unassigned'];
      else values = issue.assigneeId ? [issue.assigneeId, issue.assignee?.name, issue.assignee?.email] : ['unassigned', 'none'];
      break;
    case 'label':
      values = (issue.labels ?? []).flatMap(label => typeof label === 'string' ? [label] : [label.id, label.name]);
      break;
    case 'project':
      values = [issue.projectId, issue.projectKey];
      break;
    case 'priority':
      return compare(Number(issue.priority), node.value, node.operator);
    case 'created':
    case 'updated': {
      const actual = Date.parse(issue[node.field + 'At']);
      return Number.isFinite(actual) && compare(actual, Date.parse(node.value), node.operator);
    }
    default:
      return false;
  }
  const contains = values.filter(value => value != null).some(value => normalizeSearch(value) === expected);
  return node.operator === '!=' ? !contains : contains;
}

export function evaluateQuery(ast, issue, context = {}) {
  if (typeof ast === 'string') ast = parseQuery(ast);
  switch (ast.type) {
    case 'all': return true;
    case 'and': return evaluateQuery(ast.left, issue, context) && evaluateQuery(ast.right, issue, context);
    case 'or': return evaluateQuery(ast.left, issue, context) || evaluateQuery(ast.right, issue, context);
    case 'not': return !evaluateQuery(ast.child, issue, context);
    case 'filter': return evaluateFilter(ast, issue, context);
    case 'term':
      return [issue.key, issue.title, issue.description, issue.searchComments, ...(issue.labels ?? []).map(label => label.name ?? label)].some(value => matchesText(value, ast));
    default: throw new TypeError('Unknown query node: ' + ast.type);
  }
}

import {QUERY_FIELDS} from './parser.js';
import {normalizeSearch} from './evaluate.js';

export function quoteQueryValue(value) {
  const text = String(value);
  return /^[\p{L}\p{N}_@.\/-]+$/u.test(text) && !/^(AND|OR|NOT)$/i.test(text) ? text : JSON.stringify(text);
}

export function queryCompletionContext(source, caret = source.length) {
  caret = Math.max(0, Math.min(caret, source.length));
  let start = caret;
  let quote = null;
  let escape = false;
  let tokenStart = 0;
  for (let index = 0; index < caret; index++) {
    const character = source[index];
    if (escape) {escape = false; continue;}
    if (quote && character === '\\') {escape = true; continue;}
    if (character === quote) quote = null;
    else if (!quote && (character === '"' || character === "'")) quote = character;
    else if (!quote && /[\s()]/.test(character)) tokenStart = index + 1;
  }
  start = tokenStart;
  const fragment = source.slice(start, caret);
  const match = /^([a-z]+)(:|>=|<=|!=|>|<|=)(.*)$/i.exec(fragment);
  return {source, caret, start, end: caret, fragment, field: match?.[1]?.toLowerCase() ?? null, operator: match?.[2] ?? null, prefix: match ? match[3].replace(/^["']/, '') : fragment};
}

export function suggestQuery(source = '', catalog = {}, caret = source.length) {
  const context = queryCompletionContext(source, caret);
  const suggestions = [];
  const add = (label, replacement, description, kind = 'value') => {
    const query = source.slice(0, context.start) + replacement + source.slice(context.end);
    suggestions.push({label, replacement, description, kind, start: context.start, end: context.end, query});
  };
  if (context.field) {
    const values = context.field === 'assignee' ? [{value: '@me', label: 'Assigned to me'}, {value: 'unassigned', label: 'Unassigned'}, ...(catalog.assignees ?? [])]
      : context.field === 'priority' ? [0, 1, 2, 3, 4].map(value => ({value, label: 'Priority ' + value}))
      : context.field === 'created' || context.field === 'updated' ? (catalog.dates ?? [{value: new Date().toISOString().slice(0, 10), label: 'Today (UTC)'}])
      : catalog[context.field === 'status' ? 'statuses' : context.field === 'project' ? 'projects' : 'labels'] ?? [];
    const prefix = normalizeSearch(context.prefix);
    for (const entry of values) {
      const value = entry.value ?? entry.id ?? entry;
      const label = entry.label ?? entry.name ?? String(value);
      if (!normalizeSearch(value).startsWith(prefix) && !normalizeSearch(label).startsWith(prefix)) continue;
      add(label, context.field + context.operator + quoteQueryValue(value), entry.description ?? 'Filter by ' + context.field);
    }
  } else {
    const prefix = normalizeSearch(context.prefix);
    for (const field of QUERY_FIELDS) {
      if (field.startsWith(prefix)) add(field + (field === 'priority' ? '>=' : field === 'created' || field === 'updated' ? '>' : ':'), field + (field === 'priority' ? '>=' : field === 'created' || field === 'updated' ? '>' : ':'), 'Add a ' + field + ' filter', 'field');
    }
    for (const operator of ['AND', 'OR', 'NOT']) {
      if (operator.toLowerCase().startsWith(prefix)) add(operator, operator + ' ', operator === 'NOT' ? 'Exclude the following term or group' : 'Combine query expressions', 'operator');
    }
    if (!context.fragment) add('(group)', '()', 'Group expressions; NOT, AND, OR is the precedence order', 'group');
  }
  return [...new Map(suggestions.map(item => [item.replacement, item])).values()].slice(0, 30);
}
